package io.fireflysoftware.common.config.core.authority;
import io.fireflysoftware.common.config.core.authority.impl.TenantResourceBindingServiceImpl;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.*;
import io.fireflysoftware.common.config.models.entities.tenantbinding.TenantResourceBindingRows;
import io.fireflysoftware.common.config.models.repositories.tenantbinding.TenantResourceBindingStore;
import io.r2dbc.spi.*;
import org.fireflyframework.security.api.domain.*;
import org.junit.jupiter.api.Test;
import org.springframework.r2dbc.connection.R2dbcTransactionManager;
import org.springframework.transaction.reactive.TransactionSynchronizationManager;
import reactor.core.publisher.Mono;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class TenantResourceBindingServiceTest {
 static final UUID B=UUID.fromString("00000000-0000-0000-0000-000000000011"), S=UUID.fromString("00000000-0000-0000-0000-000000000012"), A=UUID.fromString("00000000-0000-0000-0000-000000000013"), P=UUID.fromString("00000000-0000-0000-0000-000000000014"), T=UUID.fromString(InstitutionAuthorityBudgetTest.T);
 static final Namespace NS=new Namespace(InstitutionAuthorityBudgetTest.I,"opaque / tenant");
 static Definition definition(){return new Definition(B,NS,new ResourceTenant(T),1,new Eligibility(4,S,7),InstitutionAuthorityBudgetTest.NOW.plusSeconds(30).toEpochMilli());}
 static Command command(Operation operation,long version){return new Command(A,P,operation,definition(),definition().eligibility(),version);}
 static Completion completion(Command c){return new Completion(c.actionId(),TenantResourceBindingCodec.commandDigest(c),TenantResourceBindingCodec.reference(c.definition()),c.expectedControlVersion()+1,c.operation()==Operation.TENANT_RESOURCE_BINDING_ESTABLISH?State.ACTIVE:State.REVOKED,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());}
 static final class Fixture {
  final InstitutionAuthorityBudgetTest.Time time=new InstitutionAuthorityBudgetTest.Time();
  final ConnectionFactory factory=mock(ConnectionFactory.class);final Connection connection=mock(Connection.class);
  final TenantResourceBindingStore store=mock(TenantResourceBindingStore.class);final TenantResourceBindingNativeAuthority nativeAuthority=mock(TenantResourceBindingNativeAuthority.class);
  final AtomicInteger begins=new AtomicInteger(),commits=new AtomicInteger(),rollbacks=new AtomicInteger(),closes=new AtomicInteger();final AtomicBoolean allowed=new AtomicBoolean(true);final AtomicInteger governanceCalls=new AtomicInteger();final AtomicReference<Mono<Decision>> commitPolicy=new AtomicReference<>();
  final TenantResourceBindingLookupAuthorization lookup;final InstitutionAuthorityAuthorization governance;final TenantResourceBindingServiceImpl service;
  Fixture(){
   doReturn(Mono.just(connection)).when(factory).create();when(connection.isAutoCommit()).thenReturn(true);when(connection.beginTransaction(any())).thenAnswer(x->{begins.incrementAndGet();return Mono.empty();});
   when(connection.commitTransaction()).thenAnswer(x->{commits.incrementAndGet();return Mono.empty();});when(connection.rollbackTransaction()).thenAnswer(x->{rollbacks.incrementAndGet();return Mono.empty();});when(connection.close()).thenAnswer(x->{closes.incrementAndGet();return Mono.empty();});when(connection.setAutoCommit(anyBoolean())).thenReturn(Mono.empty());
   when(store.connectionFactory()).thenReturn(factory);when(nativeAuthority.connectionFactory()).thenReturn(factory);
   lookup=new TenantResourceBindingLookupAuthorization(()->Mono.just(InstitutionAuthorityBudgetTest.principal(NS.platformTenant())),(p,a,r,c)->Mono.just(allowed.get()?Decision.permit():Decision.deny("revoked")),time,Set.of(NS.issuer()));
   governance=new InstitutionAuthorityAuthorization(()->Mono.just(InstitutionAuthorityBudgetTest.principal(T.toString())),(p,a,r,c)->{if(governanceCalls.incrementAndGet()==3&&commitPolicy.get()!=null)return commitPolicy.get();return Mono.just(allowed.get()?Decision.permit():Decision.deny("revoked"));},time,Set.of(NS.issuer()),T.toString(),true);
   service=new TenantResourceBindingServiceImpl(lookup,governance,new R2dbcTransactionManager(factory),store,nativeAuthority);
   when(store.head(anyString())).thenReturn(Mono.empty());when(store.insertDefinition(any())).thenReturn(Mono.empty());when(store.insertHead(any())).thenReturn(Mono.empty());when(store.advance(any(),any())).thenReturn(Mono.empty());
   when(nativeAuthority.openLookup(any())).thenAnswer(x->owned().thenReturn(window(1,State.ACTIVE,500)));
   when(store.current(anyString())).thenReturn(Mono.just(snapshot()));
   when(nativeAuthority.openControl(any(),any())).thenAnswer(x->{Command c=x.getArgument(1);return owned().thenReturn(new TenantResourceBindingNativeAuthority.Control(window(c.expectedControlVersion()+1,c.operation()==Operation.TENANT_RESOURCE_BINDING_ESTABLISH?State.ACTIVE:State.REVOKED,500),"https://original-maker.example.test","retained-maker",null));});
   when(nativeAuthority.finishControl(any(),any(),any(),anyLong(),any())).thenAnswer(x->owned().thenReturn(completion(x.getArgument(1))));
  }
  Mono<Void> owned(){return TransactionSynchronizationManager.forCurrentTransaction().doOnNext(context->{assertTrue(context.isActualTransactionActive());assertTrue(context.hasResource(factory));}).then();}
  TenantResourceBindingNativeAuthority.Window window(long control,State state,long until){return new TenantResourceBindingNativeAuthority.Window(TenantResourceBindingCodec.namespaceDigest(NS),definition().resourceTenant(),TenantResourceBindingCodec.reference(definition()),definition().eligibility(),control,state,true,InstitutionAuthorityBudgetTest.NOW.toEpochMilli(),InstitutionAuthorityBudgetTest.NOW.plusMillis(until).toEpochMilli(),"controlled-native-session");}
  TenantResourceBindingRows.Snapshot snapshot(){var d=definition();return new TenantResourceBindingRows.Snapshot(TenantResourceBindingCodec.namespaceDigest(NS),B,1,TenantResourceBindingCodec.definitionDigest(d),1,"ACTIVE",NS.issuer(),NS.platformTenant(),T,4,S,7,d.notAfterEpochMillis(),4,S,7,true);}
  org.fireflyframework.core.transaction.R2dbcOperationBudget budget(){return InstitutionAuthorityBudgetTest.budget(time,800);}
 }
 @Test void authenticatedLookupUsesOnePhysicalTransactionAndOriginalNamespace(){var f=new Fixture();var result=f.service.current(f.budget()).block();assertEquals(definition(),result.definition());assertEquals(1,f.begins.get());assertEquals(1,f.commits.get());assertEquals(0,f.rollbacks.get());assertEquals(1,f.closes.get());verify(f.store).current(TenantResourceBindingCodec.namespaceDigest(NS));}
 @Test void firstEstablishmentRequiresNativeAndRetainsOriginalMaker(){var f=new Fixture();var c=command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0);var done=f.service.establish(c,f.budget()).block();assertEquals(State.ACTIVE,done.state());assertEquals(1,f.begins.get());assertEquals(1,f.commits.get());verify(f.store).insertDefinition(argThat(row->row.makerSubject().equals("retained-maker")&&!row.makerSubject().equals("actual-subject")));}
 @Test void missingNativeAuthorityRefusesBeforeAnyReadOrWrite(){var f=new Fixture();doReturn(Mono.empty()).when(f.nativeAuthority).openLookup(any());assertThrows(Exception.class,()->f.service.current(f.budget()).block());verify(f.store,never()).current(anyString());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());assertThrows(NullPointerException.class,()->new TenantResourceBindingServiceImpl(f.lookup,f.governance,new R2dbcTransactionManager(f.factory),f.store,null));}
 @Test void latePolicyRefusalRollsBackAllControlWork(){var f=new Fixture();doAnswer(x->{f.allowed.set(false);return Mono.just(completion(x.getArgument(1)));}).when(f.nativeAuthority).finishControl(any(),any(),any(),anyLong(),any());assertThrows(Exception.class,()->f.service.establish(command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());assertEquals(1,f.closes.get());}
 @Test void nativeCapExpiryBeforeCommitCannotUseLongerOriginalBudget(){var f=new Fixture();doReturn(Mono.just(new TenantResourceBindingNativeAuthority.Control(f.window(1,State.ACTIVE,10),NS.issuer(),"retained-maker",null))).when(f.nativeAuthority).openControl(any(),any());doAnswer(x->{f.time.advance(11);return Mono.just(completion(x.getArgument(1)));}).when(f.nativeAuthority).finishControl(any(),any(),any(),anyLong(),any());assertThrows(Exception.class,()->f.service.establish(command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}
 @Test void missingDurableCompletionRollsBackOrdinaryWrites(){var f=new Fixture();doReturn(Mono.empty()).when(f.nativeAuthority).finishControl(any(),any(),any(),anyLong(),any());assertThrows(Exception.class,()->f.service.establish(command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),f.budget()).block());verify(f.store).insertDefinition(any());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}
 @Test void staleCurrentEligibilityCannotResolveResourceTenant(){var f=new Fixture();var row=f.snapshot();when(f.store.current(anyString())).thenReturn(Mono.just(new TenantResourceBindingRows.Snapshot(row.namespaceDigest(),B,1,row.definitionDigest(),1,"ACTIVE",NS.issuer(),NS.platformTenant(),T,4,S,7,row.notAfterEpochMillis(),5,S,7,true)));assertThrows(Exception.class,()->f.service.current(f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}
 @Test void nativeAndMappedGraphsMustBeExactlyTheOriginalFactory(){var f=new Fixture();when(f.nativeAuthority.connectionFactory()).thenReturn(mock(ConnectionFactory.class));assertThrows(IllegalArgumentException.class,()->new TenantResourceBindingServiceImpl(f.lookup,f.governance,new R2dbcTransactionManager(f.factory),f.store,f.nativeAuthority));}
 @Test void forbiddenOperationReuseAndSubscriptionExpiryAcquireNothing(){var f=new Fixture();assertThrows(Exception.class,()->f.service.establish(command(Operation.TENANT_RESOURCE_BINDING_REVOKE,1),f.budget()).block());var budget=f.budget();var call=f.service.current(budget);f.time.advance(800);assertThrows(Exception.class,call::block);assertEquals(0,f.begins.get());}
 @Test void originalExpiryAfterMappedWriteRollsBack(){var f=new Fixture();when(f.store.insertDefinition(any())).thenAnswer(x->{f.time.advance(801);return Mono.empty();});assertThrows(Exception.class,()->f.service.establish(command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}
 @Test void nativeLookupCapCoversTheMappedReadWait(){var f=new Fixture();doReturn(Mono.just(f.window(1,State.ACTIVE,10))).when(f.nativeAuthority).openLookup(any());when(f.store.current(anyString())).thenReturn(Mono.delay(java.time.Duration.ofMillis(60)).thenReturn(f.snapshot()));assertThrows(Exception.class,()->f.service.current(f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}

 @Test void immutableReplayReturnsOriginalReceiptWithoutRewritingMakerOrRows(){var f=new Fixture();var c=command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0);var done=completion(c);var d=definition();var ref=TenantResourceBindingCodec.reference(d);var ns=TenantResourceBindingCodec.namespaceDigest(NS);when(f.store.head(anyString())).thenReturn(Mono.just(new TenantResourceBindingRows.Head(ns,B,1,ref.definitionDigest(),1,"ACTIVE")));when(f.store.definition(B,1)).thenReturn(Mono.just(new TenantResourceBindingRows.Definition(B,1,ns,NS.issuer(),NS.platformTenant(),T,ref.definitionDigest(),4,S,7,d.notAfterEpochMillis(),"https://original.example.test","different-original-maker")));doReturn(Mono.just(new TenantResourceBindingNativeAuthority.Control(f.window(1,State.ACTIVE,500),null,null,done))).when(f.nativeAuthority).openControl(any(),any());assertSame(done,f.service.establish(c,f.budget()).block());verify(f.store,never()).insertDefinition(any());verify(f.store,never()).insertHead(any());verify(f.nativeAuthority,never()).finishControl(any(),any(),any(),anyLong(),any());assertEquals(1,f.commits.get());}
 @Test void authorizedRevocationUsesCurrentEpochWithoutRewritingImmutableDefinition(){var f=new Fixture();var d=definition();var ref=TenantResourceBindingCodec.reference(d);var ns=TenantResourceBindingCodec.namespaceDigest(NS);var live=new Eligibility(5,S,8);var c=new Command(A,P,Operation.TENANT_RESOURCE_BINDING_REVOKE,d,live,1);when(f.store.head(anyString())).thenReturn(Mono.just(new TenantResourceBindingRows.Head(ns,B,1,ref.definitionDigest(),1,"ACTIVE")));when(f.store.definition(B,1)).thenReturn(Mono.just(new TenantResourceBindingRows.Definition(B,1,ns,NS.issuer(),NS.platformTenant(),T,ref.definitionDigest(),4,S,7,d.notAfterEpochMillis(),NS.issuer(),"original-maker")));var w=new TenantResourceBindingNativeAuthority.Window(ns,d.resourceTenant(),ref,live,2,State.REVOKED,false,InstitutionAuthorityBudgetTest.NOW.toEpochMilli(),InstitutionAuthorityBudgetTest.NOW.plusMillis(500).toEpochMilli(),"controlled-native-session");doReturn(Mono.just(new TenantResourceBindingNativeAuthority.Control(w,null,null,null))).when(f.nativeAuthority).openControl(any(),any());assertEquals(State.REVOKED,f.service.revoke(c,f.budget()).block().state());verify(f.store,never()).insertDefinition(any());verify(f.store).advance(any(),argThat(head->head.controlVersion()==2&&head.state().equals("REVOKED")));assertEquals(1,f.commits.get());}
 @Test void replayWithoutRetainedDefinitionRefusesAndCreatesNothing(){var f=new Fixture();var c=command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0);var ns=TenantResourceBindingCodec.namespaceDigest(NS);when(f.store.head(anyString())).thenReturn(Mono.just(new TenantResourceBindingRows.Head(ns,B,1,TenantResourceBindingCodec.definitionDigest(definition()),1,"ACTIVE")));when(f.store.definition(B,1)).thenReturn(Mono.empty());doReturn(Mono.just(new TenantResourceBindingNativeAuthority.Control(f.window(1,State.ACTIVE,500),null,null,completion(c)))).when(f.nativeAuthority).openControl(any(),any());assertThrows(Exception.class,()->f.service.establish(c,f.budget()).block());verify(f.store,never()).insertDefinition(any());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}
 @Test void contradictoryOpaqueNamespaceCannotReuseProtectedSnapshot(){var f=new Fixture();var row=f.snapshot();when(f.store.current(anyString())).thenReturn(Mono.just(new TenantResourceBindingRows.Snapshot(row.namespaceDigest(),B,1,row.definitionDigest(),1,"ACTIVE",NS.issuer(),NS.platformTenant()+" ",T,4,S,7,row.notAfterEpochMillis(),4,S,7,true)));assertThrows(Exception.class,()->f.service.current(f.budget()).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}

 @Test void thisServiceRequiresExplicitReadCommittedIsolation(){var f=new Fixture();f.service.current(f.budget()).block();var definition=org.mockito.ArgumentCaptor.forClass(io.r2dbc.spi.TransactionDefinition.class);verify(f.connection).beginTransaction(definition.capture());assertEquals(io.r2dbc.spi.IsolationLevel.READ_COMMITTED,definition.getValue().getAttribute(io.r2dbc.spi.TransactionDefinition.ISOLATION_LEVEL));}
 @Test void commitPolicyWaitCannotHoldTheOwningTransactionBeyondNativeCap(){var f=new Fixture();f.commitPolicy.set(Mono.never());doReturn(Mono.just(new TenantResourceBindingNativeAuthority.Control(f.window(1,State.ACTIVE,10),NS.issuer(),"retained-maker",null))).when(f.nativeAuthority).openControl(any(),any());reactor.test.StepVerifier.withVirtualTime(()->f.service.establish(command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0),f.budget())).thenAwait(java.time.Duration.ofMillis(20)).expectError(java.util.concurrent.TimeoutException.class).verify(java.time.Duration.ofMillis(300));assertEquals(1,f.begins.get());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());assertEquals(1,f.closes.get());}

}
